const t = $('Edit Fields').first().json;
const ctx = $input.first().json || {};

const reference = String(t.order_id || '').trim();
const groupe = String(t.groupeLivreurs || ctx.groupe_livreurs || '').trim();

// LES MESSAGES CI-DESSOUS N'ONT NI DEUX-POINTS NI RETOUR A LA LIGNE.
// n8n scinde le texte d'une Error sur ces caracteres, et « Alerte Erreurs »
// n'en recevait qu'un fragment — ce qui vide de son sens un garde-fou dont
// tout l'interet est de nommer sa cause.

// Les boutons portent l'order_id, et « Acceptation Livraison » apparie la
// commande par lui. On inventait ici une reference `CMD-<chat_id>-<horodatage>`
// quand elle manquait : elle ne correspondait a aucune ligne, l'erreur qui
// suivait annoncait « Boutique introuvable », et on allait chercher le
// probleme au mauvais endroit.
if (!reference) {
  throw new Error("Dispatch impossible — l'appelant n'a transmis aucun order_id");
}

// Sans groupe de livreurs, l'envoi partait vers un destinataire vide. Il
// echouait en silence : le client avait sa confirmation, et personne n'etait
// alerte.
if (!groupe) {
  const qui = ctx.slug || ctx.nom || 'boutique inconnue';
  throw new Error(`Dispatch impossible — la boutique « ${qui} » n'a pas de groupe de livreurs configure`);
}

return [{ json: { ...ctx, reference, groupe } }];

// Le livreur lisait ceci :
//   Articles : [{"plat":"Pizza Margherita","quantité":1,"prix_unitaire":7000}]
// Il doit lire ceci :
//   Articles :
//      • 1 × Pizza Margherita — 7 000 F
//
// POURQUOI UN NOEUD DE CODE ET NON UNE EXPRESSION. Un JSON.parse qui leve dans
// l'expression du message ferait echouer TOUT l'envoi : le livreur ne serait
// jamais prevenu, et la commande resterait en cuisine. Ici, le try/catch est
// explicite et le pire cas rend le texte d'origine.

const echapper = (t) => String(t ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const brut = String($('Edit Fields').first().json.items ?? '');

let lignes = null;
try {
  lignes = JSON.parse(brut);
} catch (e) {
  lignes = null;
}

let articles_lisibles;
if (Array.isArray(lignes) && lignes.length) {
  articles_lisibles = '\n' + lignes.map((l) => {
    const q = Number(l['quantité'] ?? l.quantite ?? 1) || 1;
    const nom = echapper(l.plat ?? l.nom ?? '?');
    const pu = Number(l.prix_unitaire ?? l.prix ?? 0);
    const prix = pu ? ' — ' + (q * pu).toLocaleString('fr-FR') + ' F' : '';
    return '   • ' + q + ' × ' + nom + prix;
  }).join('\n');
} else {
  // Format inattendu : on rend le texte d'origine plutot que rien. Le livreur
  // doit pouvoir livrer meme quand la donnee nous surprend.
  articles_lisibles = ' ' + echapper(brut);
}

return $input.all().map((item) => ({
  json: { ...item.json, articles_lisibles },
}));
